"""Python-only checks of finite-slot refusal rules; no subprocesses or Java."""
import importlib.util
import json
from pathlib import Path
import tempfile
import unittest

HERE = Path(__file__).resolve().parent
spec = importlib.util.spec_from_file_location('finite_step_checks', HERE / 'run-step.py')
CONTROLLER = importlib.util.module_from_spec(spec)
spec.loader.exec_module(CONTROLLER)


class PrefixChecks(unittest.TestCase):
    def setUp(self):
        self.schedule = [{'directory': '/cohort/round-' + str(i)} for i in range(36)]

    def test_every_finite_prefix_selects_its_exact_next_position(self):
        for count in range(37):
            with self.subTest(count=count):
                result = CONTROLLER.require_prefix(self.schedule,
                    ['round-' + str(i) for i in range(count)], [f'slot-{i:02d}.json' for i in range(count)])
                self.assertEqual(result, count)

    def test_missing_predecessor_is_rejected(self):
        with self.assertRaises(ValueError):
            CONTROLLER.require_prefix(self.schedule, ['round-1'], ['slot-01.json'])

    def test_extra_future_slot_is_rejected(self):
        with self.assertRaises(ValueError):
            CONTROLLER.require_prefix(self.schedule, ['round-0', 'round-2'], ['slot-00.json'])

    def test_unclaimed_existing_next_directory_is_rejected(self):
        with self.assertRaises(ValueError):
            CONTROLLER.require_prefix(self.schedule, ['round-0'], [])

    def test_claim_without_directory_is_rejected(self):
        with self.assertRaises(ValueError):
            CONTROLLER.require_prefix(self.schedule, [], ['slot-00.json'])

    def test_extra_thirty_seventh_attempt_is_rejected(self):
        with self.assertRaises(ValueError):
            CONTROLLER.require_prefix(self.schedule, ['round-' + str(i) for i in range(37)],
                                      [f'slot-{i:02d}.json' for i in range(37)])


class RawTerminalChecks(unittest.TestCase):
    def setUp(self):
        self.temporary = tempfile.TemporaryDirectory()
        self.cohort = Path(self.temporary.name)
        self.folder = self.cohort / 'round-0'
        self.folder.mkdir()
        (self.cohort / 'slot-claims').mkdir()
        (self.cohort / 'supervision.json').write_text('{}')
        (self.cohort / 'slot-claims/slot-00.json').write_text('{}')
        self.slot = {'directory': str(self.folder), 'ordinal': 0, 'command': ['frozen-java-command']}

    def tearDown(self):
        self.temporary.cleanup()

    def process_files(self, exit_code=0, command=None):
        (self.folder / 'command.json').write_text(json.dumps({
            'argv': self.slot['command'] if command is None else command,
            'cwd': str(CONTROLLER.ROOT), 'startedEpochNs': 100}))
        (self.folder / 'process-result.json').write_text(json.dumps({
            'exitCode': exit_code, 'failure': None, 'startedEpochNs': 100, 'finishedEpochNs': 200}))

    def test_exited_jvm_without_supervisor_receipt_cannot_advance(self):
        self.process_files()
        with self.assertRaisesRegex(ValueError, 'missing normal supervisor completion receipt'):
            CONTROLLER.completed_prefix(self.cohort, {'schedule': [self.slot]}, {}, None)

    def test_failed_jvm_is_rejected_before_result_processing(self):
        self.process_files(exit_code=1)
        with self.assertRaisesRegex(ValueError, 'did not terminate normally'):
            CONTROLLER.read_run(None, {}, {}, self.slot)

    def test_mutated_java_command_is_rejected(self):
        self.process_files(command=['changed-java-command'])
        with self.assertRaisesRegex(ValueError, 'Actual Java command changed'):
            CONTROLLER.read_run(None, {}, {}, self.slot)

    def test_partial_process_without_terminal_receipt_is_rejected(self):
        (self.folder / 'command.json').write_text(json.dumps({'argv': self.slot['command']}))
        with self.assertRaises(FileNotFoundError):
            CONTROLLER.read_run(None, {}, {}, self.slot)


if __name__ == '__main__':
    unittest.main(verbosity=2)
